// Folio components
//
// Every component the Workflows screens and the task use, plus the other general-purpose UI components, in one file.
// REUSE THESE. Do not build your own version of any of them. Copy the component as written, pass props, and use its variants.
//
// Components in this file:
//   Text               Text with a named type style (display-1 ... caption-2).
//   Avatar             Initials avatar for a person. 24px in table rows.
//   Badge              Status badge, tinted pill. Supports a trailing chevron or remove icon.
//   Button             All buttons: primary, secondary, ghost-blue, ghost-gray, plain-blue and more. Large 32px, small 28px.
//   Input              Text field and search field (leading icon).
//   Checkbox           Checkbox with label.
//   StatusDot          Small colored dot for a state.
//   Tag                Small label that can show a value and be removed.
//   Filter             Filter trigger button: label, value, count badge, chevron.
//   Tooltip            Hover tooltip.
//   ListItem           Row inside a menu or list.
//   Select             Dropdown select.
//   FilterDropdown     Filter trigger plus its option panel (checkboxes, Clear, Apply).
//   SearchAndFilter    The filter bar: 'Filter by:' label, filter dropdowns, Clear, and a search field.
//   Table              Data table with sortable headers. Compose cells with Cell.
//   Cell               Table cell renderers: Text, Link, Metric, Icon, User, Status, Progress, Actions, ActionButton.
//   PageHeader         Page title row with actions.
//   Breadcrumbs        Breadcrumb trail.
//   SidenavIcon        22px icon slot used by navigation items.
//   PortalSideBarNav   The shell side navigation (expanded and collapsed).
//   CompanySwitcher    Company pill in the top bar.
//   HelpMenu           Help dropdown in the top bar.
//   UserDropdown       User menu in the top bar.
//   FeedbackButton     Thumbs up and down feedback control used inside toasts.
//   Toast              Short confirmation or status message.
//   Banner             Inline message bar: warning, error, info, success.
//   Modal              Dialog with title, body and footer actions.
//   Drawer             Side panel, 400px wide.
//   Toggle             On and off switch.
//   SegmentedButton    Segmented control for choosing one option from a few.
//   Tab                A single tab.
//   TabGroup           A row of tabs.
//   ButtonGroup        Buttons joined into one group.
//   Textarea           Multi-line text field.
//   Radio              Radio button with label.
//   AccordionSection   Collapsible section with a header.
//   FilterField        A labeled filter row used in filter lists.
//   Icon / FaI         Inline SVG icons. Use <Icon name="xmark" /> or <FaI className="fa-regular fa-xmark" />.
//
// Icons: every icon is inline SVG in FA_ICONS below, so nothing needs to load. Colors and sizes come from tokens.css.

