const FA_STYLE_WORDS = ["solid", "regular", "light", "thin", "duotone", "brands"];
const FA_SKIP = ["fw", "spin", "lg", "xs", "sm", "2x", "3x"];

function faLookup(className) {
  const tokens = String(className || "").split(/\s+/).filter(Boolean);
  const style = tokens.find((t) => t.startsWith("fa-") && FA_STYLE_WORDS.includes(t.slice(3)));
  const nameTok = tokens.find((t) => t.startsWith("fa-") && !FA_STYLE_WORDS.includes(t.slice(3)) && !FA_SKIP.includes(t.slice(3)));
  if (!nameTok) return null;
  const name = nameTok.slice(3);
  const want = style ? style.slice(3) : "solid";
  const order = want === "solid" ? ["solid", "regular"] : ["regular", "solid"];
  for (const st of order) {
    const hit = FA_ICONS[st + "/" + name];
    if (hit) return hit;
  }
  return null;
}

function FaI({ className, style, ...rest }) {
  const hit = faLookup(className);
  if (!hit) return <i className={className} style={style} {...rest} />;
  const [, , w, h] = hit.v.split(" ").map(Number);
  return (
    <svg
      viewBox={hit.v}
      width={`${(w / h).toFixed(3)}em`}
      height="1em"
      fill="currentColor"
      role="img"
      className={className}
      style={{ display: "inline-block", verticalAlign: "-0.125em", flexShrink: 0, overflow: "visible", ...style }}
      {...rest}
    >
      {hit.d.map((d, i) => <path key={i} d={d} />)}
    </svg>
  );
}

function Icon({ name, solid = false, style, ...rest }) {
  return <FaI className={`fa-${solid ? "solid" : "regular"} fa-${name}`} style={style} {...rest} />;
}

